async function seedTouristPlaces() {
  console.log('Fetching cities and categories maps...');
  const allCities = await City.find({}).lean();
  const allCategories = await Category.find({}).lean();
  const cityMap = {};
  const categoryMap = {};
  for (const c of allCities) cityMap[c.slug] = c._id;
  for (const c of allCategories) categoryMap[c.slug] = c._id;
  let inserted = 0, skipped = 0, failed = 0;
  for (const data of placesData) {
    try {
      const existing = await TouristPlace.findOne({ slug: data.slug });
      if (existing) { skipped++; continue; }
      const cityId = cityMap[data.citySlug];
      const categoryId = categoryMap[data.categorySlug];
      if (!cityId) { console.log(`  ! City not found: ${data.citySlug}`); failed++; continue; }
      if (!categoryId) { console.log(`  ! Category not found: ${data.categorySlug}`); failed++; continue; }
      const { citySlug, categorySlug, ...placeData } = data;
      await TouristPlace.create({ ...placeData, city: cityId, category: categoryId, status: 'Open' });
      inserted++;
    } catch (err) {
      console.log(`  ! Failed: ${data.name} - ${err.message}`);
      failed++;
    }
  }
  return { inserted, skipped, failed };
}

export { seedTouristPlaces };

async function main() {
  try {
    await mongoose.connect(process.env.MONGODB_URI);
    console.log('Connected to MongoDB\n');
    console.log('--- Seeding Tourist Places ---');
    const result = await seedTouristPlaces();
    console.log('\n========================================');
    console.log('      TOURIST PLACE SEEDING COMPLETE');
    console.log('========================================');
    console.log(`  Inserted: ${result.inserted}`);
    console.log(`  Skipped:  ${result.skipped}`);
    console.log(`  Failed:   ${result.failed}`);
    console.log('========================================\n');
    await mongoose.disconnect();
    process.exit(0);
  } catch (error) {
    console.error('\nSeeding error:', error);
    await mongoose.disconnect();
    process.exit(1);
  }
}

if (process.argv[1] && process.argv[1].includes('touristPlaceSeed')) {
  main();
}